import React from "react";
import { AbsoluteFill, Sequence } from "remotion";
import { N } from "./numbers";
import { Timeline, TOTAL_FRAMES } from "./Timeline";
import { Captions } from "./Captions";
import { Stage } from "./Stage";
import { colors } from "./theme";
import { EndCard } from "./scenes/EndCard";

/** Last frame of speech = end of the cut list; the reel gets a short tail for the end card. */
export const SPEECH_END = TOTAL_FRAMES;
export const REEL_FRAMES = SPEECH_END + N.endTail;

/**
 * Placeholder reel: the timeline, captions and the end card. The real Reel.tsx is GENERATED by work/gen_reel.py on top of
 * scripts/reelgen.py (start from assets/examples/gen_reel*.example.py) — anchors are words (fw("слово")), never typed
 * frame numbers, so a re-cut is a re-run.
 * Layer order (bottom → top): talking head (inside Stage) → b-roll cutaways / boards → cards, tags, stamps → audio
 * (MusicBed, Sfx) → captions.
 */
export const Reel: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: colors.bg }}>
    <Stage windows={[]}>
      <Timeline />
    </Stage>
    <Sequence name="end" from={SPEECH_END} durationInFrames={N.endTail}>
      <EndCard />
    </Sequence>
    <Sequence name="captions" durationInFrames={REEL_FRAMES}>
      <Captions src="captions/timeline.json" />
    </Sequence>
  </AbsoluteFill>
);
